mkdir -p src/sys && cat > src/lib.rs <<'EOF'
//! Cross-platform library.
//!
//! Platform-specific code lives in `src/sys/<platform>.rs`. Each backend
//! exposes the same set of items, and `sys/mod.rs` selects exactly one of
//! them with `cfg_if!`, so the rest of the crate never needs `#[cfg]`.

mod sys;

/// Returns a short, human-readable name for the platform this was built for.
pub fn platform_name() -> &'static str {
    sys::PLATFORM_NAME
}

/// Returns the platform's path-list separator (as used in `PATH`).
pub fn path_list_separator() -> char {
    sys::PATH_LIST_SEPARATOR
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn platform_name_is_not_empty() {
        assert!(!platform_name().is_empty());
    }

    #[test]
    fn path_list_separator_matches_std() {
        let joined = std::env::join_paths(["a", "b"]).unwrap();
        let expected = format!("a{}b", path_list_separator());
        assert_eq!(joined.to_str().unwrap(), expected);
    }
}
EOF
cat > src/sys/mod.rs <<'EOF'
//! Platform backend selection.
//!
//! Branches are checked in order and the first match wins, so put more
//! specific targets (e.g. `macos`) before broader ones (e.g. `unix`).

cfg_if::cfg_if! {
    if #[cfg(windows)] {
        mod windows;
        pub use self::windows::*;
    } else if #[cfg(target_os = "macos")] {
        mod macos;
        pub use self::macos::*;
    } else if #[cfg(target_os = "linux")] {
        mod linux;
        pub use self::linux::*;
    } else if #[cfg(all(target_family = "wasm", target_os = "unknown"))] {
        mod wasm;
        pub use self::wasm::*;
    } else if #[cfg(unix)] {
        mod unix;
        pub use self::unix::*;
    } else {
        compile_error!("unsupported target platform; add a backend in src/sys/");
    }
}
EOF
w() { printf '%s\n' "//! $2 backend." "" "pub const PLATFORM_NAME: &str = \"$3\";" "pub const PATH_LIST_SEPARATOR: char = '$4';" > src/sys/$1.rs; }
w windows Windows windows ';'
w macos macOS macos ':'
w linux Linux linux ':'
w wasm "WebAssembly (\`wasm32-unknown-unknown\`)" wasm ':'
w unix "Generic Unix (BSDs, illumos, etc.)" unix ':'
cat src/sys/wasm.rs
cargo fmt && cargo build 2>&1 | tail -2 && cargo test 2>&1 | grep 'test result' | head -1 && cargo clippy --all-targets -- -D warnings 2>&1 | tail -1
rustup target list --installed

